#include <bits/stdc++.h>
using namespace std;

int main() {
	int n;
	string s;
	int cnt[26]={};
	bool flag=true;

	cin>>s;
	n=s.size();
	if(n%2==1)flag=false;
	if(flag){
		for(int i=0;i<(n/2);i++){
			if(s[2*i]!=s[2*i+1])flag=false;
		}
	}
	if(flag){
		for(int i=0;i<n;i++){
			cnt[s[i]-'a']++;
		}
		for(int i=0;i<26;i++){
			if((cnt[i]!=0)&&(cnt[i]!=2))flag=false;
		}
	}

	if(flag)cout<<"Yes"<<endl;
	else cout<<"No"<<endl;
	return 0;
}

